values.content:
Write an investor update.

Company: {{ $json.companyName }}
Period: {{ $json.period }}
Frequency: {{ $json.frequency }}
Stage: {{ $json.stage || 'not specified' }}

Key metrics:
{{ Object.entries($json.metrics||{}).map(([k,v])=>k+': '+v).join('\n') || 'not provided' }}

Highlights:
{{ $json.highlights.join('\n') || 'not specified' }}

Challenges:
{{ $json.challenges.join('\n') || 'not specified' }}

Product updates:
{{ $json.productUpdates || 'not provided' }}

Sales/growth updates:
{{ $json.salesUpdates || 'not provided' }}

Team updates:
{{ $json.teamUpdates || 'not provided' }}

Fundraising status:
{{ $json.fundraisingStatus || 'not provided' }}

Ask of investors:
{{ $json.askOfInvestors.join('\n') || 'not specified' }}

Founder notes:
{{ $json.founderNotes || 'not provided' }}

Return JSON:
{"subject_line":"short subject line for the email","update":{"opening":"1-2 sentences: the most important thing that happened this period, in plain direct language","metrics_summary":"concise metrics section — what moved, direction, and brief context on why","highlights":["2-5 specific wins — concrete, not generic"],"challenges":[{"challenge":"honest description of a challenge","what_we_are_doing":"specific response or plan"}],"product":"","sales_and_growth":"","team":"","fundraising":"","ask":[{"ask":"","context":"why this ask, what the investor can do specifically"}],"closing":"1-2 sentence close — forward-looking, confident without being spin"},"one_paragraph_version":"a 100-word version of this update for investors who prefer brief","founder_notes_private":"anything from the founder notes that should be shared personally rather than in the main update — or empty string"}
